  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Interactive Snow Globe</title>
  <style>
    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    body {
      display: flex;
      justify-content: center;
      align-items: center;
      height: 100vh;
      background: linear-gradient(135deg, #667eea 0%, #764ba2 100%);
      font-family: 'Arial', sans-serif;
    }

    #container {
      text-align: center;
    }

    canvas {
      display: block;
      margin: 20px auto;
      cursor: grab;
      border: 4px solid rgba(255, 255, 255, 0.3);
      border-radius: 50%;
      background: radial-gradient(circle at 35% 35%, rgba(255,255,255,0.2), transparent);
      box-shadow: 0 20px 60px rgba(0, 0, 0, 0.4), inset 0 0 40px rgba(255,255,255,0.1);
    }

    canvas:active {
      cursor: grabbing;
    }

    h1 {
      color: white;
      font-size: 28px;
      text-shadow: 2px 2px 4px rgba(0,0,0,0.3);
      margin-bottom: 10px;
    }

    p {
      color: rgba(255,255,255,0.8);
      font-size: 14px;
    }
  </style>
</head>
